/* ===== FK RELATIONSHIP FLOW ===== */
.fk-section {
  margin-top: 14px;
  padding: 12px 14px;
  background: rgba(255,255,255,0.6);
  border-radius: 8px;
  border: 1px dashed #d0d4e0;
}
.fk-section-title {
  font-size: 11px;
  font-weight: 700;
  color: #6a6a8a;
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 6px;
}
.fk-section-title i {
  color: #e94560;
  font-size: 13px;
}
.fk-row {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  padding: 3px 0;
  font-size: 11px;
  font-family: 'Consolas', 'Courier New', monospace;
}
.fk-tbl {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  background: #ffffff;
  border: 1px solid #d8dae4;
  border-radius: 4px;
  padding: 2px 8px;
  font-weight: 600;
  color: #3a3a4a;
  font-size: 10px;
  white-space: nowrap;
}
.fk-tbl i { font-size: 9px; }
.fk-tbl.fk-source { border-left: 3px solid #2a7abf; }
.fk-tbl.fk-target { border-left: 3px solid #c8960a; }
.fk-arrow {
  color: #8888a0;
  font-size: 14px;
  opacity: 0.5;
}
.fk-field {
  font-size: 9px;
  color: #6b6b88;
  background: #f0f2f8;
  padding: 1px 5px;
  border-radius: 3px;
  font-weight: 400;
}

